            'ในสมัยที่ก่อตั้งวัดแห่งนี้ พื้นที่ซึ่งปัจจุบันคือตัวเมืองเชียงตุงยังเป็นทะเลสาบใหญ่ที่มีน้ำท่วมขัง มีเพียงหมู่บ้านเล็ก ๆ บนเนินเขาเท่านั้นที่ตั้งอยู่เหนือระดับน้ำ',
