            'ด้วยความประทับใจในการค้นพบนี้ ประธานสภาสันติภาพและการพัฒนาแห่งรัฐ พลเอกอาวุโสตานฉ่วย จึงอุปถัมภ์การก่อสร้างเจดีย์สูง 45 ฟุตขึ้นบนพื้นที่นี้ คือเจดีย์สตูรัฏฐสุมังคละ พิธีวางศิลาฤกษ์เริ่มขึ้นเมื่อวันที่ 19 ตุลาคม 1990 (ขึ้น 2 ค่ำ เดือนดะซองโมน จุลศักราช 1351) โดยมีพระเถระ ภัททันตะเขมสาระแห่งวัดจ๋องยิน ภัททันตะอาเซยะแห่งวัดธรรโมทัย และภัททันตะโชติกะแห่งวัดโฮคุน เป็นประธานฝ่ายสงฆ์ พร้อมด้วยเจ้าหน้าที่ทหารพลเรือนและประชาชนชาวเชียงตุงเข้าร่วม และแล้วเสร็จอย่างสมบูรณ์เมื่อวันที่ 7 เมษายน 1991 (แรม 9 ค่ำ เดือนดะกูหลัง จุลศักราช 1352)',
