            'บันทึกเล่าว่าหลังพระอาจารย์อูวุนนะเดินทางไปต่างแดน ศิษย์ของท่านคือ ชินก่อริยะ ได้รับการอุปสมบทจากผู้มีศรัทธาและขึ้นเป็นเจ้าอาวาส ในศักราช 767 ชินก่อริยะและผู้มีศรัทธาร่วมกันสร้างเจดีย์องค์หนึ่ง ถึงศักราช 770 ไม่มีพระสงฆ์จำพรรษาอีก ราวศักราช 775 พระสงฆ์ไทยเดินทางผ่านลาวมาถึง นำทับทิม 5 เม็ดที่ได้รับถวายจากผู้นำลาว แต่ละเม็ดว่ากันว่ามีฤทธิ์พิเศษเฉพาะตัว ด้วยความเห็นชอบของผู้มีศรัทธา ท่านได้บรรจุทับทิมไว้ในเจดีย์ใหม่ชื่อ "ซวมสัตปัตมยาเจดีย์" เจ้าฟ้าเชียงตุงเองก็สร้างเจดีย์อีกองค์ แกะสลักรูปเสือไว้ที่บันไดขึ้น และตั้งชื่อว่า "ยาซะอองมยิ่นเจดีย์" ขณะที่ประชาชนด้วยศรัทธาได้ร่วมกันสร้างเจดีย์บริวารอีก 28 องค์',
