            'ข่าวนี้ไปถึงแม้กระทั่งเทพผู้พิทักษ์เขาลอยปาแย และช้างห้าร้อยเชือกที่อาศัยอยู่บนเขาลอยปาแย หรือที่รู้จักกันในนามเขาสุวรรณสยาม ก็ออกเดินทางภายใต้การนำของหัวหน้าฝูงเพื่อมาสักการะเจดีย์ โดยมาถึงในวันเพ็ญเดือนดะบอง ในจำนวนนั้นมีช้างพลายจากเขาลอยเซาต์ตัวหนึ่งที่หลงรักช้างพังสาวจากฝูงสุวรรณสยาม และติดตามนางมาจนถึงเจดีย์',
