            'เช้าวันรุ่งขึ้น พระอาจารย์เรียกเจ้าเมืองอูขั่นเชนและรองสมาธิทั้งสอง คืออูเชนนันและอูเชนนัน มาเล่านิมิตฝันให้ฟัง และเสนอให้สร้างพระพุทธรูปสานจากไม้ไผ่ขึ้นประดิษฐาน เจ้าเมืองและผู้อาวุโสหมู่บ้านต่างเห็นชอบ จากนั้นพระอาจารย์ได้ให้คำแนะนำโดยละเอียดว่า ไม้ไผ่ที่จะใช้ต้องเป็นลำที่มีอายุหนึ่งปี ไม่มีตำหนิ ข้อห่างพอดี ตัดความยาวสามศอกครึ่ง และผู้ที่จะตัดและเก็บรวบรวมต้องเป็นหนุ่มสาวโสดแท้จริง โดยในจำนวนนั้นให้เลือกผู้ที่มีชื่อว่าฉ่วย (ทอง) เงิน (เงิน) จ่อ (อัญมณี) และฉาน เป็นพิเศษ',
