            'เริ่มตั้งแต่วันขึ้น 8 ค่ำ เดือนปยาโท พุทธศักราชพม่า 700 เริ่มการสานองค์พระนีบะยาศักดิ์สิทธิ์ เมื่อยกตอกขึ้นจากสระ ปลา กุ้ง และเต่าก็หายไปเองโดยไม่ทราบว่าไปที่ใด เมื่อกราบเรียนพระอาจารย์ ท่านอธิบายว่าสัตว์เหล่านั้นคือเทวดาและท้าวสักกะที่เสด็จมาในร่างสัตว์น้ำเพื่อสักการะตอกไม้ไผ่ที่จะกลายเป็นองค์พระ',
